INSERT INTO characters VALUES(1,1,0,60,NULL,0,3,3,3,7,0,13,100,105,5,5,0,'2025-07-05 15:40:44','2025-07-08 09:29:53');
INSERT INTO items VALUES(1,'Гострий Зуб',1,15,5,1,2,'[]','knife','weapon','common','{`agility`:1}','/images/items/knifes/knife-0.webp','Дешевий ніж з грубо обробленої сталі, який підійде для різання, кидання або відчаю, але не для серйозної битви.',20,1,'2025-07-05 15:40:34','2025-07-05 15:40:34');
INSERT INTO items VALUES(2,'Топор учня мʼясника',1,24,6,2,3,'[]','axe','weapon','common','{`strength`:1}','/images/items/axe/axe-1.png','Грубий бойовий топір, викуваний з важкого заліза. Недбалий баланс і тупе лезо не роблять його ідеальним, але в руках відчайдушного може завдати смертельного удару.',20,1,'2025-07-05 15:40:34','2025-07-05 15:40:34');
INSERT INTO items VALUES(3,'Шкіряний Дух Мандрівника',1,12,4,NULL,NULL,'{`chest`:{`min`:1,`max`:4},`belly`:{`min`:1,`max`:2}}','armor','armor','common','{`endurance`:1}','/images/items/torso/torso-1.png','Проста, але надійна броня з грубої шкіри, яку носять мисливці, початківці та ті, кому треба легкий захист без зайвого тягаря. Пахне дьогтем і пригодами.',20,1,'2025-07-05 15:40:34','2025-07-05 15:40:34');
INSERT INTO items VALUES(4,'Металевий Шолом Новачка',1,10,3,NULL,NULL,'{`head`:{`min`:1,`max`:4}}','helmet','helmet','common','{`endurance`:1}','/images/items/helmet/helmet-1.png','Старий, трохи пом’ятий шолом зі сталі. Надійно прикриває голову від легких ударів, але залишає вуха холодними. Ідеальний для тих, хто тільки починає шлях воїна.',20,1,'2025-07-05 15:40:34','2025-07-05 15:40:34');
INSERT INTO items VALUES(5,'Амулет Початківця',1,7,2,NULL,NULL,'[]','neckless','neckless','common','{`luck`:1}','/images/items/neckless/neckless-1.png','Простий дерев’яний амулет на шкіряній нитці. Допомагає трішки більше щастити в бою.',20,1,'2025-07-05 15:40:34','2025-07-05 15:40:34');
INSERT INTO items VALUES(6,'Кільце Практиканта',1,5,1,NULL,NULL,'[]','ring','ring','common','{`agility`:1}','/images/items/ring/ring-1.png','Легке металеве кільце. Його носять новачки, що прагнуть пришвидшити свої рухи.',20,1,'2025-07-05 15:40:34','2025-07-05 15:40:34');
INSERT INTO items VALUES(7,'Рукавиці Робітника',1,6,2,NULL,NULL,'{`belly`:{`min`:1,`max`:3}}','arms','arms','common','{`strength`:1}','/images/items/arms/arms-1.png','Шкіряні рукавиці з мозолями. Служать скромним, але надійним захистом для рук.',20,1,'2025-07-05 15:40:34','2025-07-05 15:40:34');
INSERT INTO items VALUES(8,'Дерев’яний Щит Початківця',1,12,4,NULL,NULL,'[]','shield','shield','common','{`block`:2}','/images/items/shield/shield-1.png','Простий щит з дуба. Може витримати кілька ударів і подарувати відчуття безпеки.',20,1,'2025-07-05 15:40:34','2025-07-05 15:40:34');
INSERT INTO items VALUES(9,'Штани Учня',1,9,3,NULL,NULL,'{`belt`:{`min`:1,`max`:2},`legs`:{`min`:2,`max`:4}}','legs','legs','common','{`endurance`:1}','/images/items/legs/legs-1.png','Зношені штани з грубого полотна. Не захистять від меча, але не сковують рухів.',20,1,'2025-07-05 15:40:34','2025-07-05 15:40:34');
INSERT INTO items VALUES(10,'Черевики Новачка',1,7,2,NULL,NULL,'{`legs`:{`min`:1,`max`:4}}','boots','boots','common','{`agility`:1}','/images/items/boots/boots-1.png','Легкі черевики зі старої шкіри. Допомагають швидше бігати та краще триматися на ногах.',20,1,'2025-07-05 15:40:34','2025-07-05 15:40:34');
