CREATE TABLE IF NOT EXISTS migrations (id INT primary key AUTO_INCREMENT not null, migration VARCHAR(255) not null, batch INT not null);
CREATE TABLE IF NOT EXISTS `users` (`id` INT primary key AUTO_INCREMENT not null, `name` VARCHAR(255) not null, `email` VARCHAR(255) not null, `email_verified_at` datetime, `password` VARCHAR(255) not null, `remember_token` VARCHAR(255), `created_at` datetime, `updated_at` datetime);
CREATE TABLE IF NOT EXISTS `password_reset_tokens` (`email` VARCHAR(255) not null, `token` VARCHAR(255) not null, `created_at` datetime, primary key (`email`));
CREATE TABLE IF NOT EXISTS `sessions` (`id` VARCHAR(255) not null, `user_id` INT, `ip_address` VARCHAR(255), `user_agent` text, `payload` text not null, `last_activity` INT not null, primary key (`id`));
CREATE TABLE IF NOT EXISTS `cache` (`key` VARCHAR(255) not null, `value` text not null, `expiration` INT not null, primary key (`key`));
CREATE TABLE IF NOT EXISTS `cache_locks` (`key` VARCHAR(255) not null, `owner` VARCHAR(255) not null, `expiration` INT not null, primary key (`key`));
CREATE TABLE IF NOT EXISTS `jobs` (`id` INT primary key AUTO_INCREMENT not null, `queue` VARCHAR(255) not null, `payload` text not null, `attempts` INT not null, `reserved_at` INT, `available_at` INT not null, `created_at` INT not null);
CREATE TABLE IF NOT EXISTS `job_batches` (`id` VARCHAR(255) not null, `name` VARCHAR(255) not null, `total_jobs` INT not null, `pending_jobs` INT not null, `failed_jobs` INT not null, `failed_job_ids` text not null, `options` text, `cancelled_at` INT, `created_at` INT not null, `finished_at` INT, primary key (`id`));
CREATE TABLE IF NOT EXISTS `failed_jobs` (`id` INT primary key AUTO_INCREMENT not null, `uuid` VARCHAR(255) not null, `connection` text not null, `queue` text not null, `payload` text not null, `exception` text not null, `failed_at` datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS `characters` (`id` INT primary key AUTO_INCREMENT not null, `user_id` INT not null, `base_health` INT not null default '0', `current_health` INT not null default '0', `health_regeneration_started_at` datetime, `is_in_battle` tinyint(1) not null default '0', `strength` INT not null default '3', `agility` INT not null default '3', `intuition` INT not null default '3', `endurance` INT not null default '3', `stat_points` INT not null default '3', `level` INT not null default '0', `experience` INT not null default '0', `gold` INT not null default '0', `wins` INT not null default '0', `losses` INT not null default '0', `draws` INT not null default '0', `created_at` datetime, `updated_at` datetime, foreign key(`user_id`) references `users`(`id`) on delete cascade);
CREATE TABLE IF NOT EXISTS `monsters` (`id` INT primary key AUTO_INCREMENT not null, `name` VARCHAR(255) not null, `base_health` INT not null default '20', `current_health` INT not null default '20', `strength` INT not null default '3', `agility` INT not null default '3', `intuition` INT not null default '3', `endurance` INT not null default '3', `level` INT not null default '0', `gold` INT not null default '0', `is_temporary` tinyint(1) not null default '0', `created_at` datetime, `updated_at` datetime);
CREATE TABLE IF NOT EXISTS `items` (`id` INT primary key AUTO_INCREMENT not null, `name` VARCHAR(255) not null, `required_level` INT not null default '1', `buy_price` INT not null default '0', `sell_price` INT not null default '0', `min_damage` INT, `max_damage` INT, `defense_by_zone` text, `type` VARCHAR(255) check (`type` in ('sword', 'axe', 'mace', 'knife', 'armor', 'helmet', 'shield', 'arms', 'legs', 'boots', 'ring', 'earrings', 'neckless')), `slot` VARCHAR(255), `rarity` VARCHAR(255) not null default 'common', `bonuses` text, `image` VARCHAR(255), `description` text, `base_max_durability` INT not null default '20', `is_shop` tinyint(1) not null default '0', `created_at` datetime, `updated_at` datetime);
CREATE TABLE IF NOT EXISTS `character_items` (`id` INT primary key AUTO_INCREMENT not null, `character_id` INT not null, `item_id` INT not null, `level` INT not null default '1', `bonuses` text, `rarity` VARCHAR(255) not null default 'common', `current_durability` INT not null default '10', `max_durability` INT not null default '10', `is_broken` tinyint(1) not null default '0', `slot` VARCHAR(255), `sell_price` INT, `location` VARCHAR(255) check (`location` in ('inventory', 'equipped', 'shop')) not null default 'shop', `created_at` datetime, `updated_at` datetime, foreign key(`character_id`) references `characters`(`id`) on delete cascade, foreign key(`item_id`) references `items`(`id`) on delete cascade);
CREATE TABLE IF NOT EXISTS `monster_items` (`id` INT primary key AUTO_INCREMENT not null, `monster_id` INT not null, `item_id` INT not null, `bonuses` text, `level` INT not null default '1', `slot` VARCHAR(255), `rarity` VARCHAR(255) not null default 'common', `sell_price` INT, `created_at` datetime, `updated_at` datetime, foreign key(`monster_id`) references `monsters`(`id`) on delete cascade, foreign key(`item_id`) references `items`(`id`) on delete cascade);
CREATE UNIQUE INDEX `users_email_unique` on `users` (`email`);
CREATE INDEX `sessions_user_id_index` on `sessions` (`user_id`);
CREATE INDEX `sessions_last_activity_index` on `sessions` (`last_activity`);
CREATE INDEX `jobs_queue_index` on `jobs` (`queue`);
CREATE UNIQUE INDEX `failed_jobs_uuid_unique` on `failed_jobs` (`uuid`);
